"""Codec boundary tests: wire expectations are independent of production decoding."""

from pathlib import Path
import struct

import cramjam
import pytest

from app import codec
from app.errors import GatewayError
from app.proto import remote_write_pb2


# Hand-derived Remote Write 1.0 wire fixture (not generated by our encoder):
# 0a 1e: WriteRequest.timeseries, 30 bytes.
#   0a 0e: TimeSeries.labels, 14 bytes.
#     0a 08 + '__name__'; 12 02 + 'up'.
#   12 0c: TimeSeries.samples, 12 bytes.
#     09 + little-endian IEEE754 1.0; 10 e8 07: timestamp varint 1000.
_LABEL = bytes.fromhex("0a085f5f6e616d655f5f12027570")
_SAMPLE = bytes.fromhex("09000000000000f03f10e807")


def _raw(data: bytes) -> bytes:
    return bytes(cramjam.snappy.compress_raw(data))


def _field(tag: int, content: bytes) -> bytes:
    # Test payloads are deliberately short: one-byte length-delimited envelope.
    assert len(content) < 128
    return bytes((tag, len(content))) + content


def _wire(label: bytes = _LABEL, sample: bytes = _SAMPLE, extra: bytes = b"") -> bytes:
    return _field(0x0A, _field(0x0A, label) + _field(0x12, sample) + extra)


def _assert_error(call, status: int, code: str):
    with pytest.raises(GatewayError) as error:
        call()
    assert (error.value.status_code, error.value.code) == (status, code)
    # Public errors cannot include a decoder exception or payload details.
    assert str(error.value) == error.value.message
    assert error.value.__cause__ is None


def test_independent_wire_fixture(settings):
    wire = bytes.fromhex(
        (Path(__file__).parents[1] / "fixtures" / "remote_write_scalar.hex").read_text(
            encoding="utf-8"
        )
    )
    message = codec.decode_write(_raw(wire), settings)
    assert len(message.timeseries) == 1
    series = message.timeseries[0]
    assert [(label.name, label.value) for label in series.labels] == [("__name__", "up")]
    assert [(sample.value, sample.timestamp) for sample in series.samples] == [(1.0, 1000)]


@pytest.mark.parametrize(
    "bits",
    [
        0x0000000000000000,
        0x8000000000000000,
        0x7FF0000000000000,
        0xFFF0000000000000,
        0x7FF8000000000001,
        0x7FF0000000000002,  # Prometheus stale marker: no floating-point arithmetic.
    ],
)
def test_float_bits_round_trip(bits, settings):
    sample = b"\x09" + struct.pack("<Q", bits) + b"\x10\xe8\x07"
    decoded = codec.decode_write(_raw(_wire(sample=sample)), settings)
    round_tripped = codec.decode_write(codec.encode_write(decoded, settings), settings)
    assert struct.pack("<d", round_tripped.timeseries[0].samples[0].value) == struct.pack(
        "<Q", bits
    )
    assert round_tripped.timeseries[0].samples[0].timestamp == 1000


def test_raw_not_framed(settings, make_write):
    wire = make_write().SerializeToString()
    assert codec.decode_write(_raw(wire), settings).SerializeToString() == wire
    framed = bytes(cramjam.snappy.compress(wire))
    _assert_error(lambda: codec.decode_write(framed, settings), 400, "invalid_snappy")


@pytest.mark.parametrize(
    ("compressed", "code"),
    [
        (b"", "empty_body"),
        (b"\x01\x00", "invalid_snappy"),  # Literal of length one, missing its byte.
        (_raw(_wire())[:-1], "invalid_snappy"),
        (_raw(b""), "empty_write"),
        (_raw(b"\x0a\x02\x0a"), "invalid_protobuf"),
    ],
    ids=["empty-body", "corrupt-snappy", "truncated-snappy", "empty-raw", "invalid-protobuf"],
)
def test_truncated_corrupt_and_empty(compressed, code, settings):
    _assert_error(lambda: codec.decode_write(compressed, settings), 400, code)


@pytest.mark.parametrize(
    "wire",
    [
        _wire() + b"\x1a\x00",  # WriteRequest metadata field 3.
        _wire(extra=b"\x1a\x00"),  # TimeSeries exemplars field 3.
        _wire(extra=b"\x22\x00"),  # TimeSeries native histograms field 4.
        _wire(label=_LABEL + b"\x18\x01"),
        _wire(sample=_SAMPLE + b"\x18\x01"),
        _wire() + b"\x08\x01",  # Known field number with unsupported wire type.
    ],
    ids=["write-request", "exemplars", "histograms", "label", "sample", "wrong-wire-type"],
)
def test_recursive_unknown_fields(wire, settings):
    _assert_error(lambda: codec.decode_write(_raw(wire), settings), 400, "unsupported_fields")


def test_empty_write_request_with_unknown_fields(settings):
    # Reject extensions, rather than dropping fields and reporting an empty write.
    _assert_error(lambda: codec.decode_write(_raw(b"\x1a\x00"), settings), 400, "unsupported_fields")


def test_declared_output_too_large_before_allocation(settings, monkeypatch):
    monkeypatch.setattr(cramjam.snappy, "decompress_raw_len", lambda data: 8388609)

    def forbidden(*args, **kwargs):
        pytest.fail("Oversized output must be rejected before allocation or decompression")

    monkeypatch.setattr(codec, "bytearray", forbidden, raising=False)
    monkeypatch.setattr(cramjam.snappy, "decompress_raw_into", forbidden)
    _assert_error(lambda: codec.decode_write(_raw(_wire()), settings), 413, "payload_too_large")


def test_decompressed_input_limit(settings):
    wire = _wire()
    limit = settings.model_copy(update={"max_decompressed_bytes": len(wire) - 1})
    _assert_error(lambda: codec.decode_write(_raw(wire), limit), 413, "payload_too_large")


def test_compressed_input_limit_before_inspection(settings, monkeypatch):
    compressed = _raw(_wire())
    limit = settings.model_copy(update={"max_compressed_bytes": len(compressed) - 1})

    def forbidden(data):
        pytest.fail("Oversized compressed input must not be inspected")

    monkeypatch.setattr(cramjam.snappy, "decompress_raw_len", forbidden)
    _assert_error(lambda: codec.decode_write(compressed, limit), 413, "payload_too_large")


def test_decompressed_length_must_match(settings, monkeypatch):
    real_into = cramjam.snappy.decompress_raw_into

    def short_result(data, output):
        return real_into(data, output) - 1

    monkeypatch.setattr(cramjam.snappy, "decompress_raw_into", short_result)
    _assert_error(lambda: codec.decode_write(_raw(_wire()), settings), 400, "invalid_snappy")


@pytest.mark.parametrize("limit_kind", ["serialized", "compressed"])
def test_output_limits(limit_kind, settings, make_write):
    message = make_write()
    if limit_kind == "serialized":
        settings = settings.model_copy(update={"max_decompressed_bytes": message.ByteSize() - 1})
    else:
        settings = settings.model_copy(update={"max_compressed_bytes": 1})
    _assert_error(lambda: codec.encode_write(message, settings), 413, "payload_too_large")


def test_limits_allow_exact_boundary(settings, make_write, pack_write):
    message = make_write()
    compressed = pack_write(message)
    exact = settings.model_copy(
        update={
            "max_decompressed_bytes": message.ByteSize(),
            "max_compressed_bytes": len(compressed),
        }
    )
    assert codec.decode_write(compressed, exact) == message
    encoded = codec.encode_write(message, exact)
    assert bytes(cramjam.snappy.decompress_raw(encoded)) == message.SerializeToString()


def test_codec_does_not_apply_later_validation(settings, make_write, pack_write):
    # Series/sample/label admission belongs to Task 3, not the transport codec.
    message = make_write(labels=[], samples=[])
    assert codec.decode_write(pack_write(message), settings) == message
    assert isinstance(codec.encode_write(message, settings), bytes)


def test_multiple_series_round_trip(settings, make_write):
    message = make_write()
    message.timeseries.add().CopyFrom(make_write(samples=[(-2.0, -1000)]).timeseries[0])
    encoded = codec.encode_write(message, settings)
    assert codec.decode_write(encoded, settings) == message
    assert isinstance(codec.decode_write(encoded, settings), remote_write_pb2.WriteRequest)
